import React, { useState, useEffect } from 'react';
import fotoBg from './foto-couple.jpg';

const WEDDING_DATE = new Date('2026-07-27T09:00:00');

export default function HeroSection({ guestName }) {
  const [countdown, setCountdown] = useState({ hari: 0, jam: 0, menit: 0, detik: 0 });

  useEffect(() => {
    const tick = () => {
      const now = new Date();
      const diff = WEDDING_DATE - now;
      if (diff > 0) {
        setCountdown({
          hari:  Math.floor(diff / (1000 * 60 * 60 * 24)),
          jam:   Math.floor((diff / (1000 * 60 * 60)) % 24),
          menit: Math.floor((diff / (1000 * 60)) % 60),
          detik: Math.floor((diff / 1000) % 60),
        });
      } else {
        setCountdown({ hari: 0, jam: 0, menit: 0, detik: 0 });
      }
    };
    tick();
    const id = setInterval(tick, 1000);
    return () => clearInterval(id);
  }, []);

  const snowflakes = Array.from({ length: 25 }, (_, i) => ({
    id: i,
    left: Math.random() * 100,
    delay: Math.random() * 6,
    duration: Math.random() * 4 + 4,
    size: Math.random() * 10 + 6,
  }));

  return (
    <section id="hero-section" style={{
      position: 'relative',
      width: '100%',
      minHeight: '100vh',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      overflow: 'hidden',
      background: '#1a0808',
    }}>
      <style>{`
        @keyframes snowfall {
          0%   { transform: translateY(-30px) rotate(0deg); opacity: 0.9; }
          100% { transform: translateY(105vh) rotate(400deg); opacity: 0; }
        }
        @keyframes heroFadeUp {
          from { opacity: 0; transform: translateY(28px); }
          to   { opacity: 1; transform: translateY(0); }
        }
        @keyframes countPulse {
          0%, 100% { transform: scale(1); }
          50%       { transform: scale(1.12); }
        }
        .hfu { animation: heroFadeUp 0.9s ease forwards; }
        .d1  { animation-delay: 0.2s;  opacity: 0; }
        .d2  { animation-delay: 0.45s; opacity: 0; }
        .d3  { animation-delay: 0.65s; opacity: 0; }
        .d4  { animation-delay: 0.85s; opacity: 0; }
        .d5  { animation-delay: 1.05s; opacity: 0; }
        .cnt { animation: countPulse 1s ease-in-out infinite; display: inline-block; }
        .open-btn { transition: transform 0.2s, box-shadow 0.2s; }
        .open-btn:hover {
          transform: scale(1.06);
          box-shadow: 0 8px 28px rgba(255,255,255,0.25) !important;
        }
      `}</style>

      {/* Background photo */}
      <img
        src={fotoBg}
        alt="Couple"
        style={{
          position: 'absolute',
          inset: 0,
          width: '100%',
          height: '100%',
          objectFit: 'cover',
          objectPosition: 'center 20%',
          zIndex: 0,
        }}
      />

      {/* Dark overlay */}
      <div style={{
        position: 'absolute', inset: 0,
        background: 'linear-gradient(to bottom, rgba(0,0,0,0.10) 0%, rgba(0,0,0,0.55) 100%)',
        zIndex: 1,
      }} />

      {/* Sparkles */}
      {snowflakes.map(s => (
        <div key={s.id} style={{
          position: 'absolute',
          left: s.left + '%',
          top: '-20px',
          color: 'rgba(255,255,255,0.75)',
          fontSize: s.size + 'px',
          pointerEvents: 'none',
          animation: `snowfall ${s.duration}s linear ${s.delay}s infinite`,
          zIndex: 2,
        }}>✦</div>
      ))}

      {/* Content */}
      <div style={{
        position: 'relative',
        zIndex: 3,
        textAlign: 'center',
        color: 'white',
        padding: '40px 20px',
        width: '100%',
        maxWidth: '600px',
      }}>

        <p className="hfu d1" style={{
          fontFamily: "'Poppins', sans-serif",
          fontSize: '1rem',
          fontWeight: 400,
          marginBottom: '10px',
          textShadow: '0 2px 12px rgba(0,0,0,0.7)',
          letterSpacing: '0.04em',
        }}>
          Kepada {guestName},
        </p>

        <h1 className="hfu d2" style={{
          fontFamily: "'Dancing Script', cursive",
          fontSize: 'clamp(2.6rem, 9vw, 4.8rem)',
          fontWeight: 700,
          marginBottom: '18px',
          textShadow: '0 3px 18px rgba(0,0,0,0.6)',
          lineHeight: 1.1,
        }}>
          Armita &amp; Febri
        </h1>

        <p className="hfu d3" style={{
          fontFamily: "'Poppins', sans-serif",
          fontSize: 'clamp(0.8rem, 2.4vw, 1rem)',
          fontWeight: 300,
          marginBottom: '6px',
          textShadow: '0 2px 12px rgba(0,0,0,0.7)',
        }}>
          Akan segera melangsungkan pernikahan pada tanggal
        </p>

        <p className="hfu d3" style={{
          fontFamily: "'Poppins', sans-serif",
          fontSize: 'clamp(1rem, 2.8vw, 1.25rem)',
          fontWeight: 700,
          marginBottom: '28px',
          textShadow: '0 2px 12px rgba(0,0,0,0.7)',
        }}>
          Minggu, 27 Juli 2026
        </p>

        <div className="hfu d4" style={{
          display: 'flex',
          gap: '18px',
          justifyContent: 'center',
          marginBottom: '36px',
        }}>
          {[
            { val: countdown.hari,  label: 'Hari' },
            { val: countdown.jam,   label: 'Jam' },
            { val: countdown.menit, label: 'Menit' },
            { val: countdown.detik, label: 'Detik' },
          ].map(({ val, label }) => (
            <div key={label} style={{ textAlign: 'center', minWidth: '52px' }}>
              <div className="cnt" style={{
                fontFamily: "'Poppins', sans-serif",
                fontSize: 'clamp(1.6rem, 5vw, 2.4rem)',
                fontWeight: 700,
                textShadow: '0 2px 10px rgba(0,0,0,0.6)',
                lineHeight: 1,
              }}>
                {String(val).padStart(2, '0')}
              </div>
              <div style={{
                fontFamily: "'Poppins', sans-serif",
                fontSize: '0.75rem',
                fontWeight: 300,
                opacity: 0.9,
                marginTop: '5px',
                letterSpacing: '0.05em',
              }}>
                {label}
              </div>
            </div>
          ))}
        </div>

        <div className="hfu d5">
          <button
            className="open-btn"
            onClick={() => {
              const el = document.getElementById('pembuka-section');
              if (el) el.scrollIntoView({ behavior: 'smooth' });
            }}
            style={{
              background: 'white',
              color: '#e91e8c',
              border: 'none',
              borderRadius: '50px',
              padding: '14px 42px',
              fontSize: '0.88rem',
              fontWeight: 700,
              fontFamily: "'Poppins', sans-serif",
              cursor: 'pointer',
              letterSpacing: '0.1em',
              display: 'inline-flex',
              alignItems: 'center',
              gap: '10px',
              boxShadow: '0 4px 20px rgba(0,0,0,0.3)',
            }}
          >
            📖 BUKA UNDANGAN
          </button>
        </div>
      </div>
    </section>
  );
}
